# TraceWeave v0.1 -> v0.3 Stage 2+3 patch
# Generated from the tested v0.3 source tree. MIT-licensed with the project.
[CmdletBinding()]
param(
    [string]$ProjectRoot = ".",
    [switch]$SkipInstall,
    [switch]$SkipTests,
    [switch]$WithProviders,
    [switch]$WithBrowser,
    [switch]$WithFull,
    [switch]$Force
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"
try { [Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false) } catch {}

function Write-Step([string]$Message) {
    Write-Host "`n==> $Message" -ForegroundColor Cyan
}

function Invoke-Checked {
    param([Parameter(Mandatory=$true)][string]$Executable,
          [Parameter(Mandatory=$false)][string[]]$ArgumentList = @())
    & $Executable @ArgumentList
    if ($LASTEXITCODE -ne 0) {
        throw "Command failed with exit code ${LASTEXITCODE}: $Executable $($ArgumentList -join ' ')"
    }
}

function Resolve-BootstrapPython {
    $candidates = @(
        @{ Exe = "py"; Prefix = @("-3.11") },
        @{ Exe = "python3"; Prefix = @() },
        @{ Exe = "python"; Prefix = @() }
    )
    foreach ($candidate in $candidates) {
        $cmd = Get-Command $candidate.Exe -ErrorAction SilentlyContinue
        if (-not $cmd) { continue }
        try {
            & $cmd.Source @($candidate.Prefix) -c "import sys; raise SystemExit(0 if sys.version_info >= (3,11) else 3)"
            if ($LASTEXITCODE -eq 0) { return $candidate }
        } catch {}
    }
    throw "Python 3.11+ was not found. Install Python 3.11 or newer and run the patch again."
}

$Root = [IO.Path]::GetFullPath((Join-Path (Get-Location) $ProjectRoot))
$PyProject = Join-Path $Root "pyproject.toml"
if (-not (Test-Path $PyProject)) {
    throw "pyproject.toml was not found in $Root. Run this patch from the TraceWeave repository root or pass -ProjectRoot."
}
$ProjectText = Get-Content -LiteralPath $PyProject -Raw
if (-not $Force -and $ProjectText -notmatch '(?m)^name\s*=\s*["'']traceweave["'']') {
    throw "This does not look like a TraceWeave checkout. Use -Force only if you intentionally want to overlay it."
}
if (-not $Force -and $ProjectText -match '(?m)^version\s*=\s*["'']([^"'']+)' ) {
    $ExistingVersion = $Matches[1]
    if ($ExistingVersion -notmatch '^0\.[123](\.|$)') {
        throw "Patch expects TraceWeave v0.1-v0.3, found version $ExistingVersion. Use -Force only after reviewing compatibility."
    }
}

Write-Host "TraceWeave Stage 2+3 patch -> v0.3.0" -ForegroundColor Green
Write-Host "Project: $Root"
Write-Host "Close any running TraceWeave process before patching so the SQLite backup is consistent." -ForegroundColor Yellow

$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupRoot = Join-Path $Root ".traceweave-patch-backup/$Timestamp"
$TempRoot = Join-Path ([IO.Path]::GetTempPath()) ("traceweave-patch-" + [Guid]::NewGuid().ToString("N"))
$ZipPath = Join-Path $TempRoot "overlay.zip"
$ExtractRoot = Join-Path $TempRoot "overlay"
New-Item -ItemType Directory -Force -Path $TempRoot, $ExtractRoot, $BackupRoot | Out-Null

$PayloadSha256 = "CA6B140FAE945F1EC73372742C547F48C266EEF1A848102E91BAA108247056F5"
