dXRlci5weVBLAQIUAxQAAAAIAABgEl3EwmEO8gAAANYBAAAWAAAAAAAAAAAAAACkAedXAQB0ZXN0cy90ZXN0X3Nlc3Npb25zLnB5
UEsBAhQDFAAAAAgAAGASXUGvHfVQAwAAQwsAABUAAAAAAAAAAAAAAKQBDVkBAHRlc3RzL3Rlc3Rfc3RvcmFnZS5weVBLAQIUAxQA
AAAIAABgEl0LrqZtWAEAAKICAAATAAAAAAAAAAAAAACkAZBcAQB0ZXN0cy90ZXN0X3V0aWxzLnB5UEsFBgAAAABLAEsAuxQAABle
AQAAAA==
'@

try {
    Write-Step "Verifying embedded patch payload"
    $bytes = [Convert]::FromBase64String(($PayloadBase64 -replace '\s',''))
    [IO.File]::WriteAllBytes($ZipPath, $bytes)
    $actual = (Get-FileHash -Algorithm SHA256 -LiteralPath $ZipPath).Hash.ToUpperInvariant()
    if ($actual -ne $PayloadSha256) { throw "Embedded payload hash mismatch. Expected $PayloadSha256, got $actual" }
    Expand-Archive -LiteralPath $ZipPath -DestinationPath $ExtractRoot -Force

    Write-Step "Backing up files that will be replaced"
    $ExtractFull = [IO.Path]::GetFullPath($ExtractRoot).TrimEnd([char]'\',[char]'/')
    $overlayFiles = Get-ChildItem -LiteralPath $ExtractRoot -File -Recurse
    foreach ($file in $overlayFiles) {
        $rel = $file.FullName.Substring($ExtractFull.Length).TrimStart([char]'\',[char]'/')
        $dest = Join-Path $Root $rel
        if (Test-Path -LiteralPath $dest) {
            $backup = Join-Path $BackupRoot $rel
            New-Item -ItemType Directory -Force -Path (Split-Path -Parent $backup) | Out-Null
            Copy-Item -LiteralPath $dest -Destination $backup -Force
        }
    }
    $StateDir = Join-Path $Root ".traceweave"
    if (Test-Path -LiteralPath $StateDir) {
        $StateBackup = Join-Path $BackupRoot "state-before-migration"
        New-Item -ItemType Directory -Force -Path $StateBackup | Out-Null
        Get-ChildItem -LiteralPath $StateDir -File -Filter "traceweave.db*" -ErrorAction SilentlyContinue | ForEach-Object {
            Copy-Item -LiteralPath $_.FullName -Destination (Join-Path $StateBackup $_.Name) -Force
        }
    }

    Write-Step "Applying Stage 2+3 source, tests and documentation"
    foreach ($file in $overlayFiles) {
        $rel = $file.FullName.Substring($ExtractFull.Length).TrimStart([char]'\',[char]'/')
        $dest = Join-Path $Root $rel
        New-Item -ItemType Directory -Force -Path (Split-Path -Parent $dest) | Out-Null
        Copy-Item -LiteralPath $file.FullName -Destination $dest -Force
    }

    # User-owned secrets/config/state are intentionally preserved.
    $EnvPath = Join-Path $Root ".env"
    if (-not (Test-Path -LiteralPath $EnvPath)) { Copy-Item (Join-Path $Root ".env.example") $EnvPath }
    $ProviderPath = Join-Path $Root "providers.toml"
    if (-not (Test-Path -LiteralPath $ProviderPath)) { Copy-Item (Join-Path $Root "providers.example.toml") $ProviderPath }

    if ($SkipInstall -and $SkipTests) {
        Write-Host "`nTraceWeave v0.3.0 files were patched successfully; installation, migration checks and tests were skipped." -ForegroundColor Green
        Write-Host "Backup: $BackupRoot"
        Write-Host "When ready, activate your environment and run: pip install -e '.[dev]' ; traceweave doctor" -ForegroundColor Yellow
        return
    }

    Write-Step "Resolving Python 3.11+"
    $VenvWindows = Join-Path $Root ".venv/Scripts/python.exe"
    $VenvUnix = Join-Path $Root ".venv/bin/python"
    $Python = $null
    if (Test-Path -LiteralPath $VenvWindows) { $Python = $VenvWindows }
    elseif (Test-Path -LiteralPath $VenvUnix) { $Python = $VenvUnix }

    if (-not $Python) {
        $bootstrap = Resolve-BootstrapPython
        Write-Host "Creating .venv with $($bootstrap.Exe)"
        $cmd = (Get-Command $bootstrap.Exe).Source
        Invoke-Checked -Executable $cmd -ArgumentList (@($bootstrap.Prefix) + @("-m", "venv", (Join-Path $Root ".venv")))
        if (Test-Path -LiteralPath $VenvWindows) { $Python = $VenvWindows }
        elseif (Test-Path -LiteralPath $VenvUnix) { $Python = $VenvUnix }
        else { throw "Virtual environment was created but its Python executable was not found." }
    }
    Write-Host "Python: $Python"

    Push-Location $Root
    try {
        if (-not $SkipInstall) {
            Write-Step "Installing/upgrading TraceWeave v0.3 dependencies"
            Invoke-Checked -Executable $Python -ArgumentList @("-m", "pip", "install", "--upgrade", "pip", "setuptools", "wheel")
            $extra = ".[dev]"
            if ($WithFull -or ($WithProviders -and $WithBrowser)) { $extra = ".[dev,full]" }
            elseif ($WithProviders) { $extra = ".[dev,providers]" }
            elseif ($WithBrowser) { $extra = ".[dev,browser]" }
            Invoke-Checked -Executable $Python -ArgumentList @("-m", "pip", "install", "-e", $extra)
        }

        Write-Step "Initializing additive v0.1 -> v0.3 storage migration"
        Invoke-Checked -Executable $Python -ArgumentList @("-c", "from traceweave.runtime import build_runtime; r=build_runtime(); print('storage migration OK:', r.settings.db_path)")

        if (-not $SkipTests) {
            Write-Step "Compiling Python sources"
            Invoke-Checked -Executable $Python -ArgumentList @("-m", "compileall", "-q", "src", "tests", "scripts")

            Write-Step "Running unit/integration tests"
            Invoke-Checked -Executable $Python -ArgumentList @("-m", "pytest", "-q")

            Write-Step "Running Stage 1 compatibility smoke test"
            Invoke-Checked -Executable $Python -ArgumentList @("scripts/smoke_test.py")

            Write-Step "Running Stage 2+3 end-to-end offline smoke test"
            Invoke-Checked -Executable $Python -ArgumentList @("scripts/smoke_stage23.py")

            Write-Step "Checking TUI module import"
            Invoke-Checked -Executable $Python -ArgumentList @("-c", "from traceweave.tui.app import TraceWeaveApp; print('TUI import OK:', TraceWeaveApp.TITLE)")

            Write-Step "Building wheel"
            Invoke-Checked -Executable $Python -ArgumentList @("-m", "build", "--wheel", "--no-isolation")
        }

        Write-Step "Running doctor"
        Invoke-Checked -Executable $Python -ArgumentList @("-m", "traceweave", "doctor")
    } finally {
        Pop-Location
    }

    Write-Host "`nTraceWeave v0.3.0 patch completed successfully." -ForegroundColor Green
    Write-Host "Backup: $BackupRoot"
    Write-Host "Start:  .\.venv\Scripts\traceweave.exe   (Windows)"
    Write-Host "        ./.venv/bin/traceweave             (Linux/macOS)"
    if ($WithBrowser -or $WithFull) {
        Write-Host "Crawl4AI package was installed. Run 'crawl4ai-setup' separately if that installation requires browser/runtime setup." -ForegroundColor Yellow
    }
    Write-Host "Provider guide: docs/PROVIDERS.md"
    Write-Host "Usage guide:    USAGE.md"
} catch {
    Write-Host "`nPATCH FAILED: $($_.Exception.Message)" -ForegroundColor Red
    Write-Host "Backed-up replaced files are under: $BackupRoot" -ForegroundColor Yellow
    Write-Host "The patch never overwrites .env, providers.toml, .git, or .traceweave source data; database migrations are additive." -ForegroundColor Yellow
    exit 1
} finally {
    if (Test-Path -LiteralPath $TempRoot) { Remove-Item -LiteralPath $TempRoot -Recurse -Force -ErrorAction SilentlyContinue }
}